package app.veyra;
import android.app.Activity;import android.content.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class ProfileAndPersonalTest {
 private Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();}
 private JSONObject title()throws Exception{return new JSONObject().put("id","42").put("vod_name","Example").put("_provider","current").put("_kind","movie");}
 @Test public void defaultDataIsPreservedAndProfilesAreIsolated()throws Exception{LibraryStore.toggle(c,title());c.getSharedPreferences("resume",0).edit().putLong("current:movie:42:id:1",12000).commit();String second=ProfileStore.create(c,"Family");ProfileStore.select(c,second);assertTrue(LibraryStore.list(c).isEmpty());assertEquals(0,ProfileStore.prefs(c,"resume").getAll().size());ProfileStore.select(c,"default");assertEquals(1,LibraryStore.list(c).size());assertEquals(12000,ProfileStore.prefs(c,"resume").getLong("current:movie:42:id:1",0));}
 @Test public void activityWithPinnedProfileKeepsOriginalIdentity(){Activity a=Robolectric.buildActivity(Activity.class).create().get();a.getIntent().putExtra("_profile","default");String other=ProfileStore.create(c,"Other");ProfileStore.select(c,other);assertEquals("default",ProfileStore.id(a));assertEquals(other,ProfileStore.id(c));}
 @Test public void pausedHistoryDoesNotRecordTitles(){ProfileStore.prefs(c,"privacy").edit().putBoolean("pauseHistory",true).commit();app.veyra.data.WatchHistory.remember(c,"current","movie","42","id:1","0","Example","",12000,90000,false);assertTrue(ProfileStore.prefs(c,"watch-history").getAll().isEmpty());}
 @Test public void collectionBackupRetainsOnlyMetadata()throws Exception{String group=PersonalStore.create(c,"Weekend");PersonalStore.add(c,group,title().put("token","secret").put("url","https://private.invalid/media"));PersonalStore.review(c,title(),8,"Watch again");JSONObject backup=VelixioData.export(c);assertFalse(backup.toString().contains("secret"));assertFalse(backup.toString().contains("private.invalid"));JSONObject safe=VelixioData.validate(backup.toString());PersonalStore.prefs(c).edit().clear().commit();VelixioData.restore(c,safe);assertEquals(1,PersonalStore.collections(c).size());assertEquals(8,new JSONObject(PersonalStore.prefs(c).getString("review:current:movie:42","{}")).getInt("rating"));}
 @Test public void malformedPersonalDataIsRejectedBeforeRestore()throws Exception{JSONObject backup=VelixioData.export(c);backup.getJSONObject("personal").put("token","private");try{VelixioData.validate(backup.toString());fail();}catch(Exception expected){}assertTrue(PersonalStore.prefs(c).getAll().isEmpty());}
 @Test public void markingWatchedClearsOnlyMatchingProgress()throws Exception{ProfileStore.prefs(c,"resume").edit().putLong("current:movie:42:id:1",5000).putLong("current:movie:420:id:1",9000).commit();PersonalStore.watched(c,title(),true);assertFalse(ProfileStore.prefs(c,"resume").contains("current:movie:42:id:1"));assertTrue(ProfileStore.prefs(c,"resume").contains("current:movie:420:id:1"));}
 @Test public void homeOrderPersistsWithinItsProfile(){HomeLayout.moveUp(c,"My list");assertEquals("My list",HomeLayout.order(c).get(0));String other=ProfileStore.create(c,"Other");ProfileStore.select(c,other);assertEquals("Continue watching",HomeLayout.order(c).get(0));}
}
